export function addEffect(s,x,z,y,color,life,vx=0,vz=0,vy=0){const pool=s.effectPool||(s.effectPool=[]),e=pool.pop()||{};e.x=x;e.z=z;e.y=y;e.color=color;e.life=life;e.vx=vx;e.vz=vz;e.vy=vy;s.effects.push(e);return e}
export function addBurst(s,x,z,color='#ff2da6',count=8){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,v=1+Math.random()*4;addEffect(s,x,z,.6+Math.random(),color,.3+Math.random()*.4,Math.cos(a)*v,Math.sin(a)*v,Math.random()*3)}}
export function updateEffects(s,dt){const pool=s.effectPool||(s.effectPool=[]);let write=0;for(let i=0;i<s.effects.length;i++){const e=s.effects[i];e.life-=dt;e.x+=(e.vx||0)*dt;e.z+=(e.vz||0)*dt;e.y+=(e.vy||0)*dt;e.vy=(e.vy||0)-5*dt;if(e.life>0)s.effects[write++]=e;else if(pool.length<256)pool.push(e)}s.effects.length=write}
